import React from 'react';

export function TarjetaCurso({ titulo, descripcion }) {
  const anioActual = new Date().getFullYear();

  return (
    <div className="tarjeta-curso">
      <h2>{titulo}</h2>
      <p>{descripcion}</p>
      <span>Año académico: {anioActual}</span>
    </div>
  );
}
